select public._wave4_upsert_formula_tools('retail-tools', '[{"slug":"retail-markdown-rate-calculator","title_ar":"حاسبة نسبة تخفيض السعر","title_en":"Retail Markdown Rate Calculator","description_ar":"احسب نسبة التخفيض من السعر الأصلي إلى سعر البيع.","description_en":"Calculate markdown percentage from original to selling price.","expression":"(original_price - selling_price) / original_price * 100","input_fields":[{"key":"original_price","label":"السعر الأصلي","type":"number","required":true,"step":0.01,"min":0.01},{"key":"selling_price","label":"سعر البيع","type":"number","required":true,"step":0.01,"min":0}],"english_fields":[{"key":"original_price","label":"Original price","type":"number","required":true,"step":0.01,"min":0.01},{"key":"selling_price","label":"Selling price","type":"number","required":true,"step":0.01,"min":0}],"submit_ar":"احسب","submit_en":"Calculate","sort_order":8101},{"slug":"gross-profit-per-transaction-calculator","title_ar":"حاسبة الربح الإجمالي لكل معاملة","title_en":"Gross Profit per Transaction Calculator","description_ar":"احسب متوسط الربح الإجمالي لكل معاملة.","description_en":"Calculate average gross profit per transaction.","expression":"(sales - cost_of_goods) / transactions","input_fields":[{"key":"sales","label":"المبيعات","type":"number","required":true,"step":0.01,"min":0},{"key":"cost_of_goods","label":"تكلفة البضاعة","type":"number","required":true,"step":0.01,"min":0},{"key":"transactions","label":"المعاملات","type":"number","required":true,"step":1,"min":1}],"english_fields":[{"key":"sales","label":"Sales","type":"number","required":true,"step":0.01,"min":0},{"key":"cost_of_goods","label":"Cost of goods","type":"number","required":true,"step":0.01,"min":0},{"key":"transactions","label":"Transactions","type":"number","required":true,"step":1,"min":1}],"submit_ar":"احسب","submit_en":"Calculate","sort_order":8102},{"slug":"retail-stock-cover-days-calculator","title_ar":"حاسبة أيام تغطية المخزون","title_en":"Retail Stock Cover