ep":1,"min":0},{"key":"units_sold","label":"الوحدات المباعة","type":"number","required":true,"step":1,"min":1}],"english_fields":[{"key":"returned_units","label":"Returned units","type":"number","required":true,"step":1,"min":0},{"key":"units_sold","label":"Units sold","type":"number","required":true,"step":1,"min":1}],"submit_ar":"احسب","submit_en":"Calculate","sort_order":8105},{"slug":"retail-promotion-sales-lift-calculator","title_ar":"حاسبة نمو المبيعات أثناء العرض","title_en":"Retail Promotion Sales Lift Calculator","description_ar":"احسب زيادة المبيعات أثناء العرض مقارنة بخط الأساس.","description_en":"Calculate promotion sales lift versus baseline sales.","expression":"(promotion_sales - baseline_sales) / baseline_sales * 100","input_fields":[{"key":"promotion_sales","label":"مبيعات العرض","type":"number","required":true,"step":0.01,"min":0},{"key":"baseline_sales","label":"المبيعات الأساسية","type":"number","required":true,"step":0.01,"min":0.01}],"english_fields":[{"key":"promotion_sales","label":"Promotion sales","type":"number","required":true,"step":0.01,"min":0},{"key":"baseline_sales","label":"Baseline sales","type":"number","required":true,"step":0.01,"min":0.01}],"submit_ar":"احسب","submit_en":"Calculate","sort_order":8106},{"slug":"retail-units-per-labor-hour-calculator","title_ar":"حاسبة الوحدات لكل ساعة عمل","title_en":"Retail Units per Labor Hour Calculator","description_ar":"احسب عدد الوحدات المباعة لكل ساعة عمل.","description_en":"Calculate units sold per labor hour.","expression":"units_sold / labor_hours","input_fields":[{"key":"units_sold","label":"الوحدات المباعة","type":"number","required":true,"step":1,"min":0},{"key":"labor_hours","label":"ساعات العمل","type":"number","required":true,"step":0.01,"min":0.01}],"english_fields":[{"key":"units_sold","label":"Units sold","type":"number","required":true,"step":1,"min":0},{"key":"labor_hours","label":"Labor hours","type":"number","required":true,"step":0.01,"min":0.01}],"submit_ar":"احسب","subm