cription_en":"Calculate retail sales growth versus a previous period.","expression":"(current_sales - previous_sales) / previous_sales * 100","input_fields":[{"key":"current_sales","label":"المبيعات الحالية","type":"number","required":true,"step":0.01,"min":0},{"key":"previous_sales","label":"المبيعات السابقة","type":"number","required":true,"step":0.01,"min":0.01}],"english_fields":[{"key":"current_sales","label":"Current sales","type":"number","required":true,"step":0.01,"min":0},{"key":"previous_sales","label":"Previous sales","type":"number","required":true,"step":0.01,"min":0.01}],"submit_ar":"احسب","submit_en":"Calculate","sort_order":8110}]'::jsonb);
